'use strict';
let takeOwner=null,takePad=null,takeOriginal=null,takeTarget=0,takeFrame=0,takeAnalyser=null,takeSource=null,takePreview=null,takeBusy=false;
const takeSheet=$('#takeSheet'),takeLevels=[],takeRecorder=new StudioTakeRecorder({
  requestStream:async()=>{if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)throw Error('Le micro nécessite un navigateur compatible et une connexion HTTPS.');await unlock();return navigator.mediaDevices.getUserMedia({audio:{echoCancellation:false,noiseSuppression:false,autoGainControl:false}})},
  makeRecorder:stream=>{const mime=['audio/webm;codecs=opus','audio/mp4','audio/webm'].find(t=>MediaRecorder.isTypeSupported(t));return new MediaRecorder(stream,mime?{mimeType:mime}:{})},
  decode:decodeStudioAudio,onChange:renderTake
});
function chooseTakeTarget(index){takeTarget=index;takePad=takeOwner.pads[index];takeOriginal=takePad.data;$('#takeTarget').value=index;const filled=takePad.data.length>1;$('#takeDestination').textContent=filled?'Remplacera « '+takePad.name+' ». Annuler ↶ permettra de le récupérer.':'Pad '+label(index)+' vide · tes autres sons restent en place.';$('#takeDestination').classList.toggle('replacement',filled)}
function showTake(index=null){if(!ready)return;stop();stopPreview();$('#sourceSheet').close();takeRecorder.discard();takeOwner=state;const local=Array.from({length:16},(_,i)=>state.bank*16+i).find(i=>state.pads[i].data.length<2),empty=local??state.pads.findIndex(p=>p.data.length<2);const target=index??(empty<0?state.selected:empty);const select=$('#takeTarget');select.replaceChildren();for(let i=0;i<64;i++){const o=document.createElement('option');o.value=i;o.textContent=label(i)+' · '+(state.pads[i].data.length>1?state.pads[i].name+' (remplacer)':'Vide');select.append(o)}chooseTakeTarget(target);$('#takeName').value='Ma voix';takeLevels.length=0;open('takeSheet');renderTake()}
$('#recordVoice').onclick=()=>showTake();$('#micStart').onclick=()=>showTake(sourceIndex);$('#takeTarget').onchange=()=>{chooseTakeTarget(+$('#takeTarget').value);renderTake()};
function stopTakePreview(){if(takePreview){const src=takePreview;takePreview=null;try{src.stop();src.disconnect()}catch{}}$('#takeListen').textContent='▶ Écouter la prise'}
function disconnectTakeMeter(){cancelAnimationFrame(takeFrame);takeFrame=0;try{takeSource?.disconnect();takeAnalyser?.disconnect()}catch{}takeSource=null;takeAnalyser=null}
function takeWave(data){const cv=$('#takeWave'),r=cv.getBoundingClientRect();if(!r.width)return;const dpr=Math.min(2,window.devicePixelRatio||1);cv.width=r.width*dpr;cv.height=r.height*dpr;const g=cv.getContext('2d');g.scale(dpr,dpr);g.strokeStyle=takeRecorder.phase==='recording'?'#ff9b81':'#d5f67b';g.lineWidth=1.3;g.beginPath();const w=r.width,h=r.height;if(data){for(let x=0;x<w;x++){let lo=0,hi=0;const from=Math.floor(x*data.length/w),to=Math.floor((x+1)*data.length/w),stride=Math.max(1,Math.floor((to-from)/16));for(let i=from;i<to;i+=stride){lo=Math.min(lo,data[i]);hi=Math.max(hi,data[i])}g.moveTo(x,h/2+lo*h*.43);g.lineTo(x,h/2+hi*h*.43)}}else{for(let x=0;x<w;x+=3){const v=takeLevels[Math.max(0,takeLevels.length-Math.floor(w/3))+Math.floor(x/3)]||0;g.moveTo(x,h/2-v*h*.43);g.lineTo(x,h/2+v*h*.43)}}g.stroke()}
function drawTakeMeter(){if(!takeSheet.open||!['ready','recording'].includes(takeRecorder.phase))return;if(!takeAnalyser&&takeRecorder.stream){takeSource=audio.ctx.createMediaStreamSource(takeRecorder.stream);takeAnalyser=audio.ctx.createAnalyser();takeAnalyser.fftSize=1024;takeSource.connect(takeAnalyser)}if(takeAnalyser){const values=new Float32Array(takeAnalyser.fftSize);takeAnalyser.getFloatTimeDomainData(values);let sum=0,peak=0;for(const v of values){sum+=v*v;peak=Math.max(peak,Math.abs(v))}const rms=Math.sqrt(sum/values.length),db=20*Math.log10(Math.max(.00001,rms)),percent=Math.round(Math.max(0,Math.min(100,(db+60)/60*100)));$('#takeMeter i').style.width=percent+'%';$('#takeMeter').setAttribute('aria-valuenow',percent);$('#takeMeter').classList.toggle('hot',peak>.95);$('#takeLevel').textContent=peak>.95?'Trop fort · éloigne-toi du micro':rms<.005?'Niveau faible · rapproche-toi du micro':'Niveau correct';takeLevels.push(Math.min(1,peak));if(takeLevels.length>320)takeLevels.shift();takeWave();}if(takeRecorder.phase==='recording'){const seconds=Math.floor((Date.now()-takeRecorder.started)/1000);$('#takeTime').textContent=Math.floor(seconds/60)+':'+String(seconds%60).padStart(2,'0')+' / 0:59'}takeFrame=requestAnimationFrame(drawTakeMeter)}
function renderTake(){const phase=takeRecorder.phase,review=phase==='review',busy=['requesting','stopping','decoding'].includes(phase)||takeBusy;takeSheet.dataset.phase=phase;$('#takeState').textContent=({idle:'Micro éteint',requesting:'Autorisation du micro…',ready:'Micro prêt · pas encore enregistré',recording:'● Enregistrement en cours',stopping:'Arrêt de la prise…',decoding:'Préparation de l’écoute…',review:'Prise à écouter',error:'Micro indisponible'})[phase];$('#takePrimary').textContent=review?(takePad?.data.length>1?'Remplacer '+label(takeTarget):'Garder sur '+label(takeTarget)):({idle:'Activer le micro',requesting:'Connexion…',ready:'● Enregistrer',recording:'■ Arrêter la prise',stopping:'Arrêt…',decoding:'Préparation…',error:'Réessayer le micro'})[phase];$('#takePrimary').disabled=busy;$('#takeCancel').disabled=takeBusy;$('#takeTarget').disabled=busy||['ready','recording'].includes(phase);$('#takeReview').hidden=!review;$('#takeAgain').disabled=takeBusy;$('#takeListen').disabled=takeBusy;$('#takeError').hidden=!takeRecorder.error;$('#takeError').textContent=takeRecorder.error;$('#takeHint').textContent=phase==='recording'?'59 secondes maximum · Arrêter permet d’écouter avant de garder.':review?'Écoute la prise. Ton pad ne change qu’en la gardant.':phase==='ready'?'Le niveau bouge ? Touche Enregistrer quand tu es prêt.':'Aucun pad ne change avant « Garder ».';if(!['ready','recording'].includes(phase)){disconnectTakeMeter();$('#takeMeter i').style.width='0%';$('#takeMeter').setAttribute('aria-valuenow',0);$('#takeLevel').textContent=review?'Écoute sans effet · les effets du pad seront ajoutés ensuite.':'Le micro sera activé à ta demande.';$('#takeTime').textContent=review?(takeRecorder.draft.data.length/RATE).toFixed(2)+' s':'0:00';requestAnimationFrame(()=>takeWave(takeRecorder.draft?.data));}else if(!takeFrame)takeFrame=requestAnimationFrame(drawTakeMeter)}
$('#takePrimary').onclick=async()=>{if(takeBusy)return;const phase=takeRecorder.phase;if(['idle','error'].includes(phase)){await takeRecorder.connect();return}if(phase==='ready'){takeLevels.length=0;takeRecorder.start();return}if(phase==='recording'){takeRecorder.stop();return}if(phase!=='review')return;const draft=takeRecorder.draft;try{if(state!==takeOwner||state.pads[takeTarget]!==takePad||takePad.data!==takeOriginal)throw Error('Le projet ou le pad a changé. Choisis de nouveau une destination.');audioMemory(takeTarget,draft.data,draft.right);takeBusy=true;renderTake();stopTakePreview();remember();audio.stop(takeTarget);const name=$('#takeName').value.trim()||'Ma voix';state.pads[takeTarget]={...M.blank(),name,data:draft.data,right:draft.right};state.selected=takeTarget;state.bank=Math.floor(takeTarget/16);padTool='play';$$('[data-pad-tool]').forEach(el=>{const on=el.dataset.padTool==='play';el.classList.toggle('active',on);el.setAttribute('aria-pressed',on)});changed();render();takeBusy=false;closeTake();showEditor();message('Prise gardée sur '+label(state.selected)+' · ajuste la découpe ou reviens jouer.')}catch(e){takeBusy=false;$('#takeError').hidden=false;$('#takeError').textContent=e.message;$('#takePrimary').disabled=false;$('#takeCancel').disabled=false;$('#takeTarget').disabled=false}};
$('#takeListen').onclick=async()=>{if(takePreview){stopTakePreview();return}try{await unlock();if(takeRecorder.phase!=='review'||!takeSheet.open)return;const draft=takeRecorder.draft,buffer=audio.ctx.createBuffer(draft.right?2:1,draft.data.length,RATE);buffer.copyToChannel(draft.data,0);if(draft.right)buffer.copyToChannel(draft.right,1);const src=audio.ctx.createBufferSource();src.buffer=buffer;src.connect(audio.ctx.destination);takePreview=src;$('#takeListen').textContent='■ Arrêter l’écoute';src.onended=()=>{src.disconnect();if(takePreview===src){takePreview=null;$('#takeListen').textContent='▶ Écouter la prise'}};src.start()}catch(e){$('#takeError').hidden=false;$('#takeError').textContent=e.message}};
$('#takeAgain').onclick=()=>{stopTakePreview();takeRecorder.discard();takeLevels.length=0;takeRecorder.connect()};
function cleanTake(){stopTakePreview();disconnectTakeMeter();takeRecorder.discard()}function closeTake(){cleanTake();takeSheet.close()}$('#takeCancel').onclick=closeTake;takeSheet.addEventListener('close',()=>{if(!takeSheet.open)cleanTake()});takeSheet.addEventListener('cancel',e=>{if(takeBusy){e.preventDefault();return}if(takeRecorder.phase==='recording'){e.preventDefault();takeRecorder.stop()}});
window.addEventListener('resize',()=>{if(takeSheet.open)takeWave(takeRecorder.draft?.data)});document.addEventListener('visibilitychange',()=>{if(document.hidden){stopTakePreview();if(['ready','requesting'].includes(takeRecorder.phase))takeRecorder.discard()}});window.addEventListener('pagehide',()=>takeRecorder.discard());
// Keep global actions understandable without relying on tooltips.
const directCore=renderDirect;renderDirect=()=>{directCore();const p=state.pads[state.selected];$('#soloClear').hidden=!state.pads.some(p=>p.solo);$('#quickMute').setAttribute('aria-label',p.muted?'Réactiver le pad sélectionné':'Rendre muet le pad sélectionné');$('#quickSolo').setAttribute('aria-label',p.solo?'Quitter le solo du pad sélectionné':'Isoler le pad sélectionné');$('#selectedInfo').textContent+=(p.muted?' · MUET':'')+(p.solo?' · SOLO':'');};
const fxTabCore=setRackTab;setRackTab=tab=>{fxTabCore(tab);$('#fxReset').textContent=tab==='rack'?'Vider le rack':'Relâcher les effets'};setRackTab(rackTab);
const targetCore=renderRackTarget;renderRackTarget=()=>{targetCore();$('#rackBypass').textContent=rackBypass?'Sans effets':'Avec effets';$('#rackBypass').setAttribute('aria-label',rackBypass?'Réactiver les effets de la cible':'Écouter la cible sans ses effets')};
renderDirect();

$('#soloClear').onclick=()=>{remember();for(const p of state.pads)p.solo=false;changed();render();message('Tous les pads peuvent jouer. Les pads muets restent muets.')};
